    outputs = [launch.output for launch in launches]
    result = proc.run(
        [sys.executable, str(PY_CLI), "agent", "collect-results", "--timeout", opts.timeout, "--summary-only", *outputs]
    )
    blocks = _split_summary_blocks(result.stdout if result.returncode == 0 else "")
    failed: list[int] = []
    for pos, launch in enumerate(launches):
        idx = launch.idx
        output = launch.output
        status, reviewer_file = _parse_block(blocks[pos] if pos < len(blocks) else "")
        if status in {"OK", "cap_hit"}:
            if status == "OK" and result_pattern is not None:
                check_file = reviewer_file or output
                if not Path(check_file).is_file():
                    _err(
                        "dispatch-with-waterfall.sh: result file not readable for --require-result-pattern check: "
                        f"{check_file}"
                    )
                    drops[idx] = DropState("result-unreadable", f"result file not readable: {check_file}")
                    failed.append(idx)
                    continue
                content = Path(check_file).read_text(encoding="utf-8", errors="replace")
                if not result_pattern.search(content):
                    drops[idx] = DropState("result-gate-miss", _snippet_from_file(check_file))
                    failed.append(idx)
                    continue
            if status == "OK" and first_line_pattern is not None:
                check_file = reviewer_file or output
                if not Path(check_file).is_file():
                    _err(
                        "dispatch-with-waterfall.sh: result file not readable for --require-first-line-pattern check: "
                        f"{check_file}"
                    )
                    drops[idx] = DropState("result-unreadable", f"result file not readable: {check_file}")
                    failed.append(idx)
                    continue
                content = Path(check_file).read_text(encoding="utf-8", errors="replace")
                first_nonblank = _first_nonblank_trimmed(content)
                if not first_line_pattern.search(first_nonblank):
                    if not first_nonblank:
                        drops[idx] = DropState("empty", "")
                        failed.append(idx)
                        continue
                    if not _salvage_first_line(check_file, first_line_pattern):
                        drops[idx] = DropState("format-gate-miss", _snippet_from_file(check_file))
                        failed.append(idx)
                        continue
            final_outputs[idx] = reviewer_file or output
            final_tools[idx] = launch.tool
            drops[idx] = DropState()
        else:
            stderr_snippet = _snippet_from_file(f"{output}.launch-stderr")
            detail = f"STATUS={status or 'unknown'}"
            if stderr_snippet:
                detail = f"{detail} {stderr_snippet}"
            drops[idx] = DropState("collector-failure", detail)
            failed.append(idx)
    return failed


def _write_counter(path: str, combined_fallback: int) -> None:
    if not path:
        return
    prior = 0
    try:
        raw = Path(path).read_text(encoding="utf-8", errors="replace").strip()
        if raw.isdigit():
            prior = int(raw, 10)
    except OSError:
        pass
    fd, tmp = tempfile.mkstemp(prefix=f"{Path(path).name}.tmp.", dir=str(Path(path).parent))
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        _ = handle.write(f"{prior + combined_fallback}\n")
    _ = Path(tmp).replace(path)


def _flatten_field(text: str) -> str:
    return text.replace("\t", " ").replace("\n", " ").replace("\r", " ")


def _write_drops(path: str, slots: Sequence[Slot], final_outputs: Sequence[str], drops: Sequence[DropState]) -> str:
    paths_dir = Path(path).parent
    tmp = ""
    try:
        fd, tmp = tempfile.mkstemp(prefix=".dispatch-waterfall-drops.", dir=str(paths_dir))
        drop_any = False
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            for idx, slot in enumerate(slots):
                if final_outputs[idx]:
                    continue
                drop_any = True
                _ = handle.write(
                    f"{_flatten_field(slot.name)}\t{_flatten_field(slot.tool)}\t{drops[idx].reason or 'unknown'}\t{drops[idx].detail}\n"
                )
        if not drop_any:
            Path(tmp).unlink(missing_ok=True)
            return ""
        dropped_slots_file = f"{path}.dropped-slots"
        _ = Path(tmp).replace(dropped_slots_file)
        return dropped_slots_file
    except OSError as exc:
        if tmp:
            with contextlib.suppress(OSError):
                Path(tmp).unlink()
        raise ValidationError(f"dispatch-with-waterfall.sh: dropped-slots sidecar not writable: {path}") from exc


def _write_paths_file(path: str, final_outputs: Sequence[str], *, no_fallback: bool) -> None:
    paths_dir = Path(path).parent
    tmp = ""
    try:
    sentinels: Sequence[str],
    *,
    timeout: int = WAIT_DEFAULT_TIMEOUT,
    poll_interval: float | None = None,
    clock: WaitClock | None = None,
    emit_fn: Callable[[str], None] = logging_util.emit,
    diagnostic_fn: Callable[[str], None] = logging_util.diagnostic,
) -> int:
    """Wait for reviewer sentinel files and emit DONE/TIMEOUT rows."""
    if poll_interval is None:
        raw = os.environ.get("WAIT_FOR_REVIEWERS_POLL_INTERVAL", WAIT_DEFAULT_POLL_INTERVAL)
        parsed = _parse_poll_interval(raw)
        if parsed is None:
            diagnostic_fn(f"Error: WAIT_FOR_REVIEWERS_POLL_INTERVAL must be a positive number, got '{raw}'")
            return 1
        poll_interval = parsed
    clock = clock or WaitClock()
    max_polls = wait_max_polls(timeout, poll_interval)
    total = len(sentinels)
    found: dict[int, str] = {}
    found_count = 0
    checks = 0
    suspend_refunds = 0
    last_progress_minute = 0
    start = clock.now()

    def check_sentinels() -> None:
        nonlocal found_count
        for idx, sentinel in enumerate(sentinels, start=1):
            if idx in found:
                continue
            if Path(sentinel).is_file():
                exit_code = _read_exit_code(sentinel)
                found[idx] = exit_code
                found_count += 1
                diagnostic_fn(f"\n✓ {_sentinel_name(sentinel)}: exit={exit_code}")

    check_sentinels()
    while found_count < total and checks < max_polls:
        iter_start = clock.now()
        diagnostic_fn(".")
        checks += 1
        elapsed_minute = int((clock.now() - start) // 60)
        if elapsed_minute >= 1 and elapsed_minute != last_progress_minute:
            diagnostic_fn(f"\n⏳ Waiting: {elapsed_minute}m elapsed, {checks} checks, {found_count}/{total} done")
            last_progress_minute = elapsed_minute
        clock.sleep(poll_interval)
        check_sentinels()
        iter_delta = int(clock.now() - iter_start)
        if iter_delta > SUSPEND_REFUND_SECONDS:
            diagnostic_fn(f"\n⚠ suspend detected — iteration took {iter_delta}s, not counting toward poll budget")
            if suspend_refunds < max_polls:
                checks -= 1
                suspend_refunds += 1

    elapsed = int(clock.now() - start)
    diagnostic_fn("\n")
    timed_out = 0
    for idx, sentinel in enumerate(sentinels, start=1):
        name = _sentinel_name(sentinel)
        if idx in found:
            emit_fn(f"DONE {idx} {name}: exit={found[idx]}")
        else:
            emit_fn(f"TIMEOUT {idx} {name}")
            timed_out += 1
    if timed_out:
        diagnostic_fn(f"⚠ {timed_out}/{total} reviewer(s) timed out after {timeout} seconds")
    else:
        diagnostic_fn(f"✓ All {total} reviewer(s) completed in {elapsed}s")
    return 0


def wait_reviewers_main(argv: list[str] | None = None) -> int:
    args_list = sys.argv[1:] if argv is None else argv
    try:
        parsed = _parse_wait_args(args_list)
    except SystemExit as exc:
        return int(exc.code or 0)
    if parsed is None:
        return 1
    timeout, sentinels = parsed
    raw_poll = os.environ.get("WAIT_FOR_REVIEWERS_POLL_INTERVAL", WAIT_DEFAULT_POLL_INTERVAL)
    poll_interval = _parse_poll_interval(raw_poll)
    if poll_interval is None:
        print(f"Error: WAIT_FOR_REVIEWERS_POLL_INTERVAL must be a positive number, got '{raw_poll}'", file=sys.stderr)
        return 1
    logging_util.quiet_init(argv0="wait-for-reviewers.sh")
    return wait_reviewers(sentinels, timeout=timeout, poll_interval=poll_interval)


def _generated_paths(tsv_path: Path | None = None) -> set[str]:
    path = tsv_path if tsv_path is not None else GENERATORS_TSV
    out: set[str] = set()
    try:
        for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            parts = line.split("\t")
            if len(parts) == GENERATORS_TSV_COLUMNS and parts[1]:
                out.add(parts[1])

